package app.morphe.extension.chmate;

/** Public page statistics only; missing ranks are never inferred. */
final class HissiActivityGraph {
    static final String SCRIPT = "(function(){\nif(!/(^|\\.)hissi\\.org$/.test(location.hostname))return;\nvar old=document.getElementById('haiagaru-hour-graph');if(old){old.remove();return;}\nvar counts=Array(24).fill(0),found=false;\nArray.from(document.querySelectorAll('table')).some(function(table){var rows=Array.from(table.rows);for(var i=0;i<rows.length-1;i++){var labels=Array.from(rows[i].cells).map(function(c){return c.textContent.trim();});if(labels.length<24)continue;var start=labels.findIndex(function(t){return /^(0|00)(時)?$/.test(t);});if(start<0||labels.length-start<24)continue;var nums=Array.from(rows[i+1].cells).map(function(c){return c.textContent.trim().replace(/,/g,'');});if(nums.length<start+24)continue;var values=nums.slice(start,start+24);if(values.every(function(n){return /^\\d+$/.test(n);})){counts=values.map(Number);found=true;return true;}}return false;});\nif(!found){document.querySelectorAll('dl dt').forEach(function(dt){var m=dt.textContent.match(/\\d{4}\\/\\d{2}\\/\\d{2}[^\\d]*(\\d{1,2}):\\d{2}/);if(m){counts[+m[1]]++;}});}\nvar panel=document.createElement('section');panel.id='haiagaru-hour-graph';panel.style.cssText='padding:16px;margin:12px;border:1px solid currentColor;border-radius:12px;';\nvar title=document.createElement('h3');title.textContent='時間帯別の書き込み数';panel.appendChild(title);\nvar rank=(document.body.innerText||'').match(/([\\d,]+)\\s*位\\s*\\/\\s*([\\d,]+)\\s*ID/);var label=document.createElement('p');label.textContent=rank?'当日順位 '+rank[1]+'位 / '+rank[2]+' ID':'当日順位：取得できません';panel.appendChild(label);\nvar note=document.createElement('p');note.textContent=found?'Hissi掲載の時間帯別集計':'表示中の投稿から集計';panel.appendChild(note);\nvar graph=document.createElement('div');graph.style.cssText='display:flex;align-items:end;gap:3px;height:150px;overflow-x:auto;';var max=Math.max.apply(null,counts.concat([1]));\ncounts.forEach(function(n,h){var col=document.createElement('div');col.style.cssText='display:flex;flex-direction:column;justify-content:end;text-align:center;min-width:22px;flex:1;font-size:11px;height:100%;';var value=document.createElement('span');value.textContent=n;var bar=document.createElement('div');bar.style.cssText='background:#4b9fe1;min-height:1px;height:'+Math.round(n/max*105)+'px;';bar.setAttribute('aria-label',h+'時 '+n+'件');var hour=document.createElement('span');hour.textContent=h;col.append(value,bar,hour);graph.appendChild(col);});panel.appendChild(graph);\nvar post=document.querySelector('dl');if(post)post.parentNode.insertBefore(panel,post);else document.body.prepend(panel);panel.scrollIntoView({block:'start'});\n})()";
    private HissiActivityGraph(){}
}
